head.b:skin:
*{box-sizing:border-box}
html,body{margin:0;height:100%;background:#0c1024;color:#eef0f8;font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;overflow:hidden;-webkit-user-select:none;user-select:none}
button{font:inherit;cursor:pointer}
.hide{display:none!important}
.screen{position:fixed;inset:0;display:flex;align-items:center;justify-content:center}
.panel{background:#f7f5ef;color:#1d1d24;border-radius:14px;padding:22px 24px;max-width:560px;width:calc(100% - 32px);max-height:calc(100% - 32px);overflow:auto;box-shadow:0 10px 40px rgba(0,0,0,.5)}
.panel h1{margin:0 0 6px;font-size:26px}.panel h2{margin:0 0 10px;font-size:20px}
.panel p{line-height:1.5;margin:8px 0}
.mute{color:#5c6170;font-size:14px}
.btn{background:#d9561e;color:#fff;border:0;border-radius:9px;padding:11px 18px;font-weight:700;font-size:16px}
.btn.alt{background:#fff;color:#1d1d24;border:1px solid #c9ccd6}
.btn:disabled{background:#c9ccd6;color:#fff;cursor:not-allowed}
input.txt{font:inherit;font-size:18px;padding:10px 12px;border-radius:8px;border:1px solid #b9bdc9;width:100%;margin:6px 0 12px}
.err{color:#b3261e;font-size:14px;min-height:1.2em}
/* slides */
#slide{background:#0c1024}
#slide .sbox{display:flex;flex-direction:column;align-items:center;gap:14px;width:min(900px,calc(100% - 24px));max-height:100%;padding:12px}
#slide img{max-width:100%;max-height:calc(100vh - 210px);border-radius:12px;display:block}
#slide .stext{background:#14235c;border:3px solid #e8ecff;border-radius:10px;padding:14px 18px;font-size:18px;line-height:1.5;width:100%}
/* team pick */
.dgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(96px,1fr));gap:10px;margin:12px 0}
.dpick{background:none;border:0;padding:0;position:relative;border-radius:12px}
.dpick.sel{outline:4px solid #d9561e;outline-offset:2px}
.lgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:12px;margin:12px 0}
.lpick{background:#1c2450;border:2px solid #3a4580;border-radius:14px;padding:10px;cursor:pointer;color:#fff;font:700 14px system-ui,sans-serif;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;min-height:90px}
#lgrid{grid-template-columns:repeat(auto-fit,minmax(110px,1fr))}
@media (max-width:520px){#lgrid{grid-template-columns:repeat(2,1fr)}}
.lpick img{height:170px;max-width:100%;object-fit:contain}
.lpick.hat img{height:70px}
.lpick.sel{border-color:#ffd34d;box-shadow:0 0 0 3px #ffd34d}
.dpick.off{opacity:.35}
.lv{position:absolute;top:-6px;right:-6px;background:#d9561e;color:#fff;font-weight:800;font-size:12px;border-radius:99px;padding:2px 7px;z-index:3}
/* card frame (same look as Bad Mascots) */
.frame{padding:4px;border-radius:12px;background:#8d949b;position:relative}
.frame.rare{background:linear-gradient(135deg,#f5f7fa,#9aa5b1 45%,#e8edf2 60%,#8a96a3)}
.frame.legendary{background:linear-gradient(135deg,#fff3b0,#d9a520 45%,#fff0a0 60%,#c8921a)}
.frame .inner{background:#fbf6e9;border-radius:9px;padding:4px}
.frame .nm{background:#fff;border:1px solid #3a3f47;border-radius:6px;padding:2px 4px;font-size:11px;font-weight:700;line-height:1.15;min-height:2.3em;display:flex;align-items:center;justify-content:center;text-align:center;color:#1f2933;margin-bottom:4px}
.frame img{display:block;width:100%;aspect-ratio:3/4;object-fit:cover;border:1.5px solid #3a3f47;border-radius:5px;background:#fff}
.frame .st{display:flex;align-items:center;justify-content:space-between;gap:2px;margin-top:4px}
.frame .pill{display:flex;align-items:center;gap:2px;background:#fff;border:1.5px solid #3a3f47;border-radius:99px;padding:1px 5px 1px 3px;font-weight:800;font-size:14px;line-height:1.2;color:#1f2933}
.frame .pill.r{padding:1px 3px 1px 5px}
.frame .pill svg{width:12px;height:12px}
.frame .up{text-align:center;line-height:1.05}.frame .up i{display:block;font-style:normal;font-size:6px;color:#66707a;font-weight:700}.frame .up b{font-size:12px;color:#2e8b57}
/* world */
#world{flex-direction:column;justify-content:flex-start;gap:6px;padding-top:6px}
#hud{display:flex;align-items:center;gap:8px;width:var(--gw);max-width:calc(100% - 12px);flex-wrap:wrap}
#obj{flex:1;min-width:180px;background:#14235c;border:2px solid #e8ecff;border-radius:8px;padding:6px 10px;font-size:14px;line-height:1.3}
.hb{background:#f7f5ef;color:#1d1d24;border:0;border-radius:8px;padding:8px 12px;font-weight:700;font-size:14px}
#stage{position:relative}
#cv{display:block;border-radius:6px;image-rendering:auto}
#mini{position:absolute;top:8px;right:8px;display:grid;grid-template-columns:repeat(5,14px);gap:2px;padding:4px;background:rgba(10,14,40,.75);border-radius:6px}
#mini i{width:14px;height:10px;background:#33406e;border-radius:2px}
#mini i.v{background:#6b7bb8}#mini i.h{background:#ffd34d}
#dlg{position:absolute;left:8px;right:8px;bottom:8px;background:#14235c;border:3px solid #e8ecff;border-radius:10px;padding:12px 16px;font-size:17px;line-height:1.45;cursor:pointer;box-shadow:0 6px 20px rgba(0,0,0,.5)}
#dlg .who{font-weight:800;color:#ffd34d;margin-bottom:2px}
#dlg img{display:block;max-height:calc(var(--gh) * .45);max-width:100%;border-radius:8px;margin:0 auto 8px}
#dlg img.pt{float:left;height:84px;width:auto;max-height:none;margin:-4px 12px 0 -4px;border-radius:10px;background:#1c2f78}
#dlg::after{content:"";display:block;clear:both}
#dlg .more{float:right;opacity:.8;font-size:14px;margin-top:6px}
#pad{display:none;gap:6px;align-items:center;justify-content:center;margin-top:4px}
@media (pointer:coarse){#pad{display:flex}}
#pad .grid{display:grid;grid-template-columns:repeat(3,58px);grid-template-rows:repeat(3,52px);gap:4px}
#pad button{background:#f7f5ef;color:#1d1d24;border:0;border-radius:10px;font-size:22px;font-weight:800;touch-action:none}
#flash{position:fixed;inset:0;background:#fff;opacity:0;pointer-events:none;z-index:50}
/* battle */
#battle{z-index:20;background-size:cover;background-position:center;align-items:stretch}
#battle .shade{position:absolute;inset:0;background:rgba(6,8,24,.55)}
/* classic side-view battle: monsters on the left, Louie's cards on the right, blue windows along the bottom */
#battle .shade{background:linear-gradient(to bottom,rgba(6,8,24,.15),rgba(6,8,24,.35) 60%,rgba(6,8,24,.7))}
#battle .bwrap{position:relative;display:grid;grid-template-rows:1fr auto;gap:10px;width:100%;height:100%;padding:12px;max-width:1500px;margin:0 auto;box-sizing:border-box}
.bfield{display:flex;justify-content:space-between;align-items:flex-end;min-height:0;padding:0 2%}
.bteam{display:flex;flex-direction:column;align-items:center}
@media (max-aspect-ratio:1/1){.bfield{flex-direction:column;justify-content:space-evenly;align-items:center}}
.brow{display:flex;gap:10px;justify-content:center;align-items:flex-start}
.brow .bc:nth-child(2){margin-top:calc(var(--cw)*0.16)}
.brow .bc:nth-child(3){margin-top:calc(var(--cw)*0.32)}
.bteam.me .brow .bc:nth-child(1){margin-top:calc(var(--cw)*0.32)}
.bteam.me .brow .bc:nth-child(3){margin-top:0}
.bbar{display:flex;flex-direction:column;gap:8px;max-width:1100px;width:100%;margin:0 auto}
.bbar .ffbox{padding:10px 14px}
.bbar .ffbox .msg{min-height:0}
.bbar .cmd{flex-direction:row;flex-wrap:wrap}
.bbar .cmd button{flex:1 1 160px;text-align:center;border:2px solid #4b5aa0;background:#1b2b6e}
.bbar .choices{display:grid;grid-template-columns:1fr 1fr;gap:0 10px}
@media (max-width:700px){.bbar .choices{grid-template-columns:1fr}}
.blab{font-size:13px;font-weight:800;letter-spacing:.08em;background:rgba(10,14,40,.7);padding:3px 10px;border-radius:6px;margin:2px 0}
.bc{position:relative;width:var(--cw);transition:filter .3s,opacity .3s}
.bc.pickable{cursor:pointer}.bc.pickable .frame{box-shadow:0 0 0 2px #ffffff88}
.bc.sel .frame{box-shadow:0 0 0 3px #e07a1f,0 0 24px rgba(224,122,31,.75)}
.bc.tgt{cursor:crosshair}.bc.tgt .frame{box-shadow:0 0 0 3px #f27d70,0 0 22px rgba(242,125,112,.7)}
.bc.ko{filter:grayscale(1) brightness(.5);opacity:.6}
.kot{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font:800 28px Georgia,serif;color:#fff;letter-spacing:.2em;text-shadow:0 0 10px #000;pointer-events:none}
.bside{display:flex;flex-direction:column;gap:10px;justify-content:flex-end;min-height:0}
.ffbox{background:#14235c;border:3px solid #e8ecff;border-radius:10px;padding:12px 14px;box-shadow:0 6px 20px rgba(0,0,0,.5)}
.ffbox .msg{font-size:17px;line-height:1.4;min-height:2.8em}
.turn{font-size:13px;opacity:.9;margin-bottom:6px}
.pips i{display:inline-block;width:10px;height:10px;border-radius:50%;background:#ffd34d;margin-left:4px}.pips i.u{background:#3b467a}
.cmd{display:flex;flex-direction:column;gap:6px}
.cmd button{text-align:left;background:transparent;color:#fff;border:0;border-radius:6px;padding:8px 10px;font-size:18px;font-weight:700}
.cmd button:hover:not(:disabled){background:#2a3c8a}
.cmd button:before{content:"\25B6";font-size:12px;margin-right:8px;opacity:0}
.cmd button:hover:before{opacity:1}
.cmd button:disabled{opacity:.4;cursor:default}
.choice{display:block;width:100%;text-align:left;padding:9px 12px;margin:6px 0 0;border:2px solid #4b5aa0;border-radius:8px;background:#1b2b6e;color:#fff;font-size:16px}
.choice.right{background:#12301f;border-color:#62c98f}.choice.wrong{background:#3a1814;border-color:#f27d70}
.q{font-size:17px;font-weight:700;margin-bottom:4px}
.spk{font:inherit;font-weight:700;padding:8px 14px;margin-top:6px;border-radius:99px;border:0;background:#e98a30;color:#1a0f08}
.typerow{display:flex;gap:8px;margin-top:8px}.typein{font:inherit;font-size:18px;flex:1;padding:8px 10px;border-radius:8px;border:2px solid #4b5aa0;background:#0f173f;color:#fff}
.typein.right{border-color:#62c98f}.typein.wrong{border-color:#f27d70}
.fl{position:absolute;left:50%;top:28%;transform:translateX(-50%);font:800 30px system-ui,sans-serif;pointer-events:none;z-index:40;text-shadow:0 0 8px #000,0 2px 0 #000;white-space:nowrap}
.fl.dmg{color:#ff6b5e}.fl.up{color:#7dffb0}
.fxo{position:absolute;inset:0;border-radius:12px;pointer-events:none;z-index:35}
.tag{display:inline-block;font-size:12px;font-weight:800;padding:2px 8px;border-radius:99px;background:#ffd34d;color:#3a2a00;margin-bottom:6px}
